package io.github.linker2k.myembro.fonts

import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonPrimitive
import kotlinx.serialization.json.booleanOrNull
import kotlinx.serialization.json.doubleOrNull
import kotlinx.serialization.json.jsonArray
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import kotlinx.serialization.json.longOrNull

/**
 * `assets/fonts/inkstitch-catalog.json` (generated by tools/inkstitch_catalog.py): pre-digitized
 * Ink/Stitch fonts, each with three pinned files. Parsed without org.json so unit tests can read it.
 */
object InkStitchCatalog {
    const val ASSET = "fonts/inkstitch-catalog.json"

    fun parse(json: String): List<CatalogFont> =
        Json.parseToJsonElement(json).jsonObject.getValue("fonts").jsonArray.map { element ->
            val o = element.jsonObject
            fun s(key: String) = o.getValue(key).jsonPrimitive.content
            fun d(key: String) = o.getValue(key).jsonPrimitive.doubleOrNull ?: error("$key is not a number")
            val url = s("url"); val metaUrl = s("metaUrl"); val licenseUrl = s("licenseUrl")
            require(listOf(url, metaUrl, licenseUrl).all { it.startsWith("https://") }) { "Only https downloads: ${s("id")}" }
            CatalogFont(
                id = s("id"), name = s("name"), nameKo = null, kind = CatalogFont.Kind.INKSTITCH_SVG,
                scripts = o.getValue("scripts").jsonArray.map { it.jsonPrimitive.content },
                license = s("license"), designer = (o["designer"] as? JsonPrimitive)?.content.orEmpty(),
                url = url, sha256 = s("sha256"), size = o.getValue("size").jsonPrimitive.longOrNull ?: 0L,
                licenseUrl = licenseUrl, licenseSha256 = s("licenseSha256"), licenseInFont = false,
                recommendedMinHeightMm = d("recommendedMinHeightMm"),
                qualityGrade = QualityGrade.valueOf(s("qualityGrade")),
                metaUrl = metaUrl, metaSha256 = s("metaSha256"),
                recommendedMaxHeightMm = d("recommendedMaxHeightMm"),
                thinThreadRequired = (o["thinThreadRequired"] as? JsonPrimitive)?.booleanOrNull ?: false,
                coverage = (o["lowercase"] as? JsonPrimitive)?.booleanOrNull?.let { lower ->
                    CatalogFont.GlyphCoverage(lower, (o["digits"] as? JsonPrimitive)?.booleanOrNull ?: true,
                        (o["hangul"] as? JsonPrimitive)?.booleanOrNull ?: false, (o["letterCase"] as? JsonPrimitive)?.content.orEmpty())
                },
            )
        }
}
